// ---------------------------------------------------------------------------------------------------------------------
// constructors of table entries
// ---------------------------------------------------------------------------------------------------------------------
constexpr uint32_t kAuto = kParamAutomatable;
constexpr uint32_t kMod = kParamAutomatable | kParamModulatable;

/** Continuous parameter (exp skew if skew != 1). */
constexpr ParamInfo cont (const char* key, const char* name, const char* group, float mn, float mx, float def, Unit unit, uint32_t flags,
                          int decimals = 1, float skew = 1.0f)
{
    return { hashKey (key), key, name, group, mn, mx, def, skew, 0.0f, skew != 1.0f ? Scale::exp_skew : Scale::linear, unit, flags,
             nullptr, 0, ChoiceSet::none, static_cast<uint8_t> (decimals), 0 };
}

/** Integer valued parameter on a grid of 1 (voices, semitones). */
constexpr ParamInfo whole (const char* key, const char* name, const char* group, float mn, float mx, float def, Unit unit, uint32_t flags)
{
    return { hashKey (key), key, name, group, mn, mx, def, 1.0f, 1.0f, Scale::linear, unit, flags, nullptr, 0, ChoiceSet::none, 0, 0 };
}

/** Choice parameter over a list of names. */
template <size_t N>
constexpr ParamInfo pick (const char* key, const char* name, const char* group, const char* const (&list)[N], int def)
{
    return { hashKey (key), key, name, group, 0.0f, static_cast<float> (N - 1), static_cast<float> (def), 1.0f, 1.0f, Scale::stepped, Unit::none,
             kParamAutomatable | kParamStepped, list, static_cast<uint16_t> (N), ChoiceSet::list, 0, 0 };
}

/** Choice parameter over the first n names of a list, starting at the entry `first` (a window into a longer list). */
constexpr ParamInfo window (const char* key, const char* name, const char* group, const char* const* list, int first, int n, int def)
{
    return { hashKey (key), key, name, group, 0.0f, static_cast<float> (n - 1), static_cast<float> (def), 1.0f, 1.0f, Scale::stepped, Unit::none,
             kParamAutomatable | kParamStepped, list + first, static_cast<uint16_t> (n), ChoiceSet::list, 0, 0 };
}

constexpr ParamInfo onOff (const char* key, const char* name, const char* group, bool def)
{
    return pick (key, name, group, kOffOn, def ? 1 : 0);
}

constexpr ParamInfo modSource (const char* key, const char* name, const char* group)
{
    return { hashKey (key), key, name, group, 0.0f, static_cast<float> (kNumModSources), 0.0f, 1.0f, 1.0f, Scale::stepped, Unit::none,
             kParamAutomatable | kParamStepped, nullptr, 0, ChoiceSet::modSource, 0, 0 };
}

/** The destination choice: 0 = none, then every modulatable parameter. kNumModDestinations is checked against the table below. */
constexpr int kNumModDestinations = 1 + 269;
constexpr ParamInfo modDestination (const char* key, const char* name, const char* group)
{
    return { hashKey (key), key, name, group, 0.0f, static_cast<float> (kNumModDestinations - 1), 0.0f, 1.0f, 1.0f, Scale::stepped, Unit::none,
             kParamAutomatable | kParamStepped, nullptr, 0, ChoiceSet::modDestination, 0, 0 };
}

// percent shorthand: 0..100 unless stated
#define SB_PCT(key, name, group, def, flags) cont (key, name, group, 0.0f, 100.0f, def, Unit::percent, flags)
#define SB_PCT_RANGE(key, name, group, mn, mx, def, flags) cont (key, name, group, mn, mx, def, Unit::percent, flags)

// ---------------------------------------------------------------------------------------------------------------------
// repeated groups
// ---------------------------------------------------------------------------------------------------------------------
#define SB_OSC(N, WARPLIST)                                                                                                                      \
    onOff ("osc" #N ".on", "Osc " #N " On", "Osc " #N, N == 1),                                                                                  \
    SB_PCT ("osc" #N ".level", "Osc " #N " Level", "Osc " #N, 50.0f, kMod),                                                                      \
    SB_PCT_RANGE ("osc" #N ".pan", "Osc " #N " Pan", "Osc " #N, -100.0f, 100.0f, 0.0f, kMod),                                                    \
    whole ("osc" #N ".transpose", "Osc " #N " Transpose", "Osc " #N, -48.0f, 48.0f, 0.0f, Unit::semitone, kMod),                                \
    cont ("osc" #N ".tune", "Osc " #N " Tune", "Osc " #N, -100.0f, 100.0f, 0.0f, Unit::cents, kMod),                                              \
    pick ("osc" #N ".wavetable", "Osc " #N " Wavetable", "Osc " #N " / Wavetable", kWavetables, kWavetableSaw),                                  \
    SB_PCT ("osc" #N ".frame", "Osc " #N " Frame", "Osc " #N " / Wavetable", 0.0f, kMod),                                                        \
    SB_PCT_RANGE ("osc" #N ".frame_spread", "Osc " #N " Unison Frame Spread", "Osc " #N " / Wavetable", -100.0f, 100.0f, 0.0f, kMod),            \
    cont ("osc" #N ".phase", "Osc " #N " Phase", "Osc " #N, 0.0f, 360.0f, 0.0f, Unit::degrees, kMod, 0),                                         \
    SB_PCT ("osc" #N ".random_phase", "Osc " #N " Random Phase", "Osc " #N, 0.0f, kMod),                                                         \
    SB_DEST (N),                                                                                                                             \
    whole ("osc" #N ".unison.voices", "Osc " #N " Unison Voices", "Osc " #N " / Unison", 1.0f, 16.0f, 1.0f, Unit::voices, kMod),                \
    SB_PCT ("osc" #N ".unison.detune", "Osc " #N " Unison Detune", "Osc " #N " / Unison", 25.0f, kMod),                                          \
    cont ("osc" #N ".unison.detune_curve", "Osc " #N " Unison Detune Curve", "Osc " #N " / Unison", -5.0f, 5.0f, 1.5f, Unit::none, kMod),        \
    SB_PCT ("osc" #N ".unison.spread", "Osc " #N " Unison Stereo Spread", "Osc " #N " / Unison", 100.0f, kMod),                                  \
    SB_PCT ("osc" #N ".unison.blend", "Osc " #N " Unison Blend", "Osc " #N " / Unison", 80.0f, kMod),                                            \
    pick ("osc" #N ".unison.stack", "Osc " #N " Unison Stack", "Osc " #N " / Unison", kStackStyles, 0),                                          \
    pick ("osc" #N ".morph.type", "Osc " #N " Morph Type", "Osc " #N " / Spectral Morph", kMorphTypes, 0),                                       \
    SB_PCT ("osc" #N ".morph.amount", "Osc " #N " Morph Amount", "Osc " #N " / Spectral Morph", 50.0f, kMod),                                    \
    SB_PCT_RANGE ("osc" #N ".morph.spread", "Osc " #N " Morph Spread", "Osc " #N " / Spectral Morph", -100.0f, 100.0f, 0.0f, kMod),             \
    pick ("osc" #N ".warp.type", "Osc " #N " Warp Type", "Osc " #N " / Warp", WARPLIST, 0),                                                      \
    SB_PCT ("osc" #N ".warp.amount", "Osc " #N " Warp Amount", "Osc " #N " / Warp", 50.0f, kMod),                                                \
    cont ("osc" #N ".warp.phase", "Osc " #N " Warp Phase", "Osc " #N " / Warp", 0.0f, 360.0f, 180.0f, Unit::degrees, kMod, 0),                  \
    SB_PCT_RANGE ("osc" #N ".warp.spread", "Osc " #N " Warp Spread", "Osc " #N " / Warp", -100.0f, 100.0f, 0.0f, kMod)

#define SB_FILTER(KEY, NAME, GROUP, ON, MODEL)                                                                                                   \
    onOff (KEY ".on", NAME " On", GROUP, ON),                                                                                                    \
    pick (KEY ".model", NAME " Model", GROUP, kFilterModels, MODEL),                                                                             \
    pick (KEY ".style", NAME " Style", GROUP, kFilterStyles, 0),                                                                                 \
    cont (KEY ".cutoff", NAME " Cutoff", GROUP, 20.0f, 20000.0f, 12000.0f, Unit::Hz, kMod, 1, 0.3f),                                            \
    SB_PCT (KEY ".resonance", NAME " Resonance", GROUP, 20.0f, kMod),                                                                            \
    cont (KEY ".drive", NAME " Drive", GROUP, 0.0f, 20.0f, 0.0f, Unit::dB, kMod),                                                                \
    SB_PCT (KEY ".blend", NAME " Blend", GROUP, 0.0f, kMod),                                                                                     \
    SB_PCT (KEY ".mix", NAME " Mix", GROUP, 100.0f, kMod),                                                                                       \
    SB_PCT_RANGE (KEY ".keytrack", NAME " Key Tracking", GROUP, -100.0f, 100.0f, 0.0f, kMod),                                                    \
    cont (KEY ".comb_offset", NAME " Comb Blend Offset", GROUP " / Model Settings", 0.0f, 84.0f, 42.0f, Unit::semitone, kMod),                  \
    SB_PCT (KEY ".formant.x", NAME " Formant X", GROUP " / Model Settings", 50.0f, kMod),                                                        \
    SB_PCT (KEY ".formant.y", NAME " Formant Y", GROUP " / Model Settings", 50.0f, kMod),                                                        \
    SB_PCT_RANGE (KEY ".formant.resonance", NAME " Formant Resonance", GROUP " / Model Settings", 30.0f, 100.0f, 85.0f, kMod),                   \
    SB_PCT_RANGE (KEY ".formant.spread", NAME " Formant Spread", GROUP " / Model Settings", -100.0f, 100.0f, 0.0f, kMod),                        \
    cont (KEY ".formant.transpose", NAME " Formant Transpose", GROUP " / Model Settings", -12.0f, 12.0f, 0.0f, Unit::semitone, kMod, 2)

#define SB_ENV(N)                                                                                                                                \
