#define SB_LFO(N)                                                                                                                                \
    pick ("lfo" #N ".shape", "LFO " #N " Shape", "LFO " #N, kLfoShapes, 0),                                                                      \
    cont ("lfo" #N ".rate", "LFO " #N " Rate", "LFO " #N, 0.01f, 200.0f, 2.0f, Unit::Hz, kMod, 2, 0.25f),                                        \
    pick ("lfo" #N ".sync", "LFO " #N " Sync", "LFO " #N, kLfoSync, 0),                                                                          \
    pick ("lfo" #N ".division", "LFO " #N " Division", "LFO " #N, kDivisions, 8),                                                                \
    pick ("lfo" #N ".sync_type", "LFO " #N " Trigger", "LFO " #N, kLfoSyncTypes, 0),                                                             \
    cont ("lfo" #N ".phase", "LFO " #N " Phase", "LFO " #N, 0.0f, 360.0f, 0.0f, Unit::degrees, kMod, 0),                                         \
    cont ("lfo" #N ".fade_in", "LFO " #N " Fade In", "LFO " #N, 0.0f, 8000.0f, 0.0f, Unit::ms, kMod, 1, 0.4f),                                   \
    cont ("lfo" #N ".delay", "LFO " #N " Delay", "LFO " #N, 0.0f, 4000.0f, 0.0f, Unit::ms, kMod, 1, 0.4f),                                       \
