#define SB_SLOT(S)                                                                                                                               \
    modSource ("mod" #S ".source", "Mod " #S " Source", "Mod Matrix / Slot " #S),                                                                \
    modDestination ("mod" #S ".destination", "Mod " #S " Destination", "Mod Matrix / Slot " #S),                                                 \
    SB_PCT_RANGE ("mod" #S ".amount", "Mod " #S " Amount", "Mod Matrix / Slot " #S, -100.0f, 100.0f, 0.0f, kAuto),                               \
    cont ("mod" #S ".power", "Mod " #S " Curve", "Mod Matrix / Slot " #S, -10.0f, 10.0f, 0.0f, Unit::none, kAuto),                               \
    onOff ("mod" #S ".bipolar", "Mod " #S " Bipolar", "Mod Matrix / Slot " #S, false),                                                           \
    onOff ("mod" #S ".stereo", "Mod " #S " Stereo", "Mod Matrix / Slot " #S, false),                                                             \
